#!/usr/bin/env python3
"""Build a self-contained current architecture report from recorded evidence.

Old preview evidence stays in reports/; only coverage-progress.json and its
explicitly referenced follow-up results are presented as current verification.
"""
from html import escape
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
REPORTS = ROOT / 'reports'


def read(path):
    return json.loads(path.read_text())


def e(value):
    return escape(str(value))


def details(title, value):
    return '<details><summary>' + e(title) + '</summary><pre>' + e(json.dumps(value, indent=2)) + '</pre></details>'


def table(headers, rows):
    return '<div class="scroll"><table><thead><tr>' + ''.join('<th>' + e(h) + '</th>' for h in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join('<td>' + e(v) + '</td>' for v in row) + '</tr>' for row in rows) + '</tbody></table></div>'


coverage = read(REPORTS / 'coverage-progress.json')
runtime = read(ROOT / 'profiles/runtime.lock.json')
sources = read(ROOT / 'profiles/sources.lock.json')['sources']
reference = read(REPORTS / 'reference-comparison.json')
sections = []


def section(anchor, title, body):
    sections.append((anchor, title, body))


section('overview', 'Delivered system', '''<p>A containerized CDA validation API, local browser workspace, Node/TypeScript client and command-line interface. Existing in-process JavaScript APIs remain available independently of the service. Submitted XML is not persisted or sent to an external validator.</p>
<div class="callout">This report describes the <strong>unreleased PR #53 candidate after preview.2</strong>. Published preview.2 artifacts and npm tags are unchanged. This is engineering evidence, not clinical certification or a claim to be the fastest validator.</div>'''
+ '<div class="cards">' + ''.join('<div class="card"><strong>' + e(value) + '</strong><span>' + e(label) + '</span></div>' for value, label in [(coverage['javascriptTests'], 'JavaScript tests'), (coverage['javaTests'], 'Java tests'), (coverage['pythonTests'], 'Python tests'), (coverage['localSnapshots'], 'Local terminology snapshots')]) + '</div>')
section('architecture', 'Architecture and request lifecycle', '''<div class="flow"><div>Browser / Node / CLI</div><b>→</b><div>Bounded admission<br>Fair upload memory queue</div><b>→</b><div>Streaming JSON<br>Strict XML + XSD</div><b>→</b><div>Compiled Schematron<br>Reviewed supplements</div><b>→</b><div>Findings + coverage<br>Locations + provenance</div></div>
<p>Patched Java 25 LTS hosts the HTTP adapter and engine. Saxon-HE 12.9 executes stylesheets compiled with SchXslt 1.10.1. The JDK XSD validator checks the pinned CDA schema; Gson serializes reports. No database, message broker, Node process or application framework is required inside the runtime container.</p>
<p>Startup verifies the extracted asset inventory, compiles schemas and profile executables once, and loads immutable operator terminology indexes. Every document owns its parser, schema validator, transformer, line lookup and bounded finding collector. There is no patient-document or result cache.</p>
<p>The releases use XPath 1.0 coercions. Compilation retains backwards-compatible semantics, makes severity explicit and assigns stable IDs to unnamed assertions. Vocabulary comparisons use complete tokens rather than substring membership. List-valued name attributes are checked token by token. Predicate-scoped vocabulary variables retain their own context.</p>
<p>Python tools prepare sources, import authorized data, verify runtime versions, check upstream releases, exercise memory pressure and generate this report. The browser is ordinary HTML/CSS/JavaScript with no external scripts, fonts, trackers or analytics.</p>''')
section('standards', 'Standards, source data and reproducibility', '<p>Official releases are pinned by immutable URL and SHA-256. Downloads are checked at build time and the per-file inventory is checked again at startup. Updates require review; validation never silently downloads new rules.</p>' + table(['Resource', 'Release', 'Official source', 'SHA-256'], [(s['id'], s['release'], s['url'], s['sha256']) for s in sources]) + '''<p>C-CDA 2.1 remains supported with the 2025SEP Schematron. New public images omit its mixed-license vocabulary; operators install the authorized exact pinned copy. Until then schema validation runs and Schematron setup is explicitly incomplete. The Node legacy API still accepts caller-provided resources.</p>
<p>C-CDA 5.0 uses the 2026JUL Schematron. Its original generation report is retained unchanged. Reviewed replacement checks are accounted for separately, and a changed upstream report requires a new review.</p>''')
section('coverage', 'What validation completion means', '''<p>The stated scope is <strong>pinned CDA XSD and C-CDA Schematron with reviewed local supplements</strong>. This is not a general FHIR StructureDefinition validator and does not certify clinical accuracy.</p>'''
+ table(['Field', 'Meaning'], [('executionComplete', 'Configured engine stages finished without failure.'), ('validationComplete', 'Execution finished, supported document-level template matched, findings were not truncated, generator replacements were reviewed, and every applicable check was determinate.'), ('valid', 'Complete within the stated scope and no errors.'), ('invalid', 'Errors found; completeness still needs inspection.'), ('incomplete', 'No errors found, but execution or applicable coverage is incomplete. This is not a pass.')])
+ '''<p>A completed invalid report is expected when checks finish and find errors. Missing datasets generate coverage findings at applicable locations, even when advisory warnings are hidden. An absent optional binding that a document does not use does not make every document incomplete. Dataset readiness remains separately visible.</p>
<p>Six restored invariants cover person names, procedure membership, procedure timestamps and a three-set location union. All omitted binding locations receive checks or explicit unknown coverage. Three CarePlanAct unions allow base CDA Act/Observation children without invented template IDs; 103 scoped assertions restore root cardinalities, fixed values, required bindings and II constraints alongside XSD and narrower profile rules.</p>
<p>Indeterminate cases include unsupported SNOMED expressions, standalone CPT/HCPCS modifiers, mismatched declared terminology editions, ambiguous scalar vocabulary values, insufficient timestamp precision, excessive grammar complexity and unvalidated BCP 47 extension semantics. Private-use language tags remain supported. Nested templates firing cannot replace a supported root document template.</p>'''
+ details('Effective coverage and CarePlan source receipts', coverage.get('effectiveCoverage', {})))
section('terminology', 'Operator terminology and licensing', '<p>The verified local pack contains <strong>' + e(coverage['localSnapshots']) + ' snapshots / ' + e(f"{coverage['localMembershipEntries']:,}") + ' membership entries</strong>, with ' + e(coverage['activeLocalIndexes']) + ' active indexes and two grammars. It enables six supplemental invariants and ' + e(coverage['supplementalBindingChecks']) + ' catalog binding checks. Public images and npm packages omit this operator data.</p>' + '''<p>UMLS 2026AB plus LOINC Complete 2.83 supplies reviewed US Core condition (262,583 pairs) and procedure (274,743 pairs) sets. SNOMED descendants use source-asserted AUI hierarchy paths and source concept IDs, not shared UMLS CUIs. The 62,110-pair Procedure hierarchy exactly matches an independent VSAC snapshot. Archive hashes, source row counts, recipe counts and source editions are recorded.</p>
<p>Source editions include SNOMED US September 2026, CPT 2026, <strong>CDT 2025</strong>, HCPCS 2026, ICD-10-CM/PCS 2027, ICD-9-CM 2014 and LOINC 2.83. These are the reviewed archive's editions; older data is never relabeled as a new edition. Explicit document version mismatches are incomplete rather than silently evaluated against another version.</p>
<p>LOINC document types are cross-checked against primary SCALE part links. UCUM uses its pinned essence grammar. BCP 47 uses the November 18, 2026 IANA registry and extension singleton registry; extension key/type semantics are not claimed.</p>
<div class="callout warning"><strong>Remaining dataset: NUBC discharge status.</strong> An operator must supply an authorized complete expansion to check that binding. No NUBC source was present in UMLS and no scraped substitute is bundled. Applicable checks remain incomplete until installed.</div>
<p>Application code is MIT licensed; terminology has separate terms. A free application, UMLS access or a notice does not automatically establish redistribution or product rights. The software does not accept licenses or collect credentials. CPT/ADA and other applicable permissions remain the operator's responsibility. See the <a href="https://www.ama-assn.org/practice-management/cpt/cpt-licensing-frequently-asked-questions-faqs">AMA guidance</a> and <a href="https://loinc.org/kb/license">LOINC license</a>.</p>
<pre>python3 scripts/import-umls.py \
  --input /private/path/umls-2026AB-full.zip \
  --loinc /private/path/Loinc_2.83.zip \
  --output terminology

python3 scripts/prepare-public-terminology.py --download --grammars --output terminology</pre><p>Full setup, SVS/FHIR import and legacy vocabulary installation: <a href="/terminology.html">operator guide in the service</a> or <a href="https://github.com/priyaranjan-tokachichu/cda-schematron-validator/blob/fix/ccda-validation-coverage/docs/terminology.md">repository documentation</a>. Restart after data changes; active indexes remain immutable.</p>''')
section('security', 'Patched Java and security boundaries', '<p>Build and runtime use <strong>Temurin ' + e(runtime['javaVersion']) + '+' + e(runtime['javaBuild']) + ' LTS</strong> on AMD64 and ARM64. This contains the November fix for <a href="' + e(runtime['advisory']) + '">CVE-2026-114938</a>. Java 27 is the newer feature line; its official image still had mixed architecture patch levels when reviewed. This choice uses the latest patched LTS available for both supported targets.</p>' + '''<p>Images are digest-pinned. CI verifies the actual JVM version/vendor in the built image, and the weekly upstream watch flags a newer selected LTS release. The API exposes the actual runtime. Older published previews do not receive this patch until rebuilt and released.</p>
<p>DTD declarations and entities are forbidden, including UTF-16 import declarations. Runtime resource resolution denies the network and paths outside trusted assets. Public routes accept XML and installed profile IDs, never arbitrary server files, URLs or executable Schematron. Input bodies, filenames, findings and parser diagnostics are not logged.</p>
<p>The container runs as non-root UID/GID 10001, with a read-only root filesystem, bounded temporary storage, dropped capabilities and no-new-privileges. Shared deployments need an authenticated HTTPS gateway and deliberate logging/retention controls. Findings can contain submitted values; callers must handle them appropriately.</p>'''
+ details('Runtime lock', runtime) + details('Point-in-time image and dependency scan', coverage.get('security', {'status': 'Final image scan pending; do not infer a passing result.'})))
section('api', 'API, UI and interoperability', table(['Route', 'Purpose'], [('POST /v1/validate', 'JSON containing XML text, profile and warning settings; structured findings.'), ('GET /v1/profiles', 'Provenance, effective/historical coverage, data readiness and active limits.'), ('GET /v1/version', 'Application, engine and actual Java runtime/vendor.'), ('GET /health/live and /health/ready', 'Health probes independent of validation queue contention.'), ('GET /openapi.json', 'OpenAPI 3.1 contract.')]) + '''<p>Findings include severity, stage, source message, rule ID, XPath, assertion test, pattern/context and available line/column. HTTP 200 means a report was produced, not a validation pass. Operational errors use distinct HTTP statuses.</p>
<p>The UI accepts an XML file, drag-and-drop or pasted text. It shows installed profiles, data/coverage limits, stage status, findings, filters, line navigation and a downloadable JSON report. Input revisions guard delayed file/example loads and stale validation responses. User-provided content is inserted as text. The blue/slate palette is independent of workplace branding, with red errors and amber coverage notices.</p>
<p>Language-neutral HTTP/JSON lets other technologies use the container. The npm package retains validate, validateAsync, both batch APIs, parseSchematron and cache APIs; their synchronous/Promise contracts remain. The legacy interpreter is partial Schematron and does not add XSD validation. The additive createClient() and CLI use the modern service. Node 22.12+ is required.</p>''')
upload = coverage['privateTerminologyUploadRegression']
section('capacity', 'Bounded capacity and memory', '''<p>Default XML limit is <strong>20 MiB decoded UTF-8</strong>, configurable with MAX_XML_MIB. Worst-case JSON escaping is allowed separately: six times the XML limit plus 64 KiB. Streaming decode avoids keeping the entire serialized body in memory.</p>
<p>Six requests may be admitted across upload, queue and validation; two workers execute validation. Uploads share a quarter-heap budget with conservative reservations and a fair queue. An admitted request waits on its original connection, up to 30 seconds, without requiring a retry. A full overall queue returns 429; an expired upload wait returns 503. Health checks remain available.</p>
<p>Increase both Java heap and container memory to allow more concurrent large uploads. More heap does not by itself guarantee faster XPath execution. Full terminology indexes are checked against estimated heap capacity before loading. The tested full-pack configuration uses a 1 GiB heap and 1.5 GiB container limit.</p>
<pre>VALIDATOR_MEMORY_LIMIT=3g VALIDATOR_JAVA_OPTIONS=-Xmx2g docker compose up -d</pre>
<p>Other limits: 128 levels, 100,000 elements, 256 attributes per element, 2,000 findings, bounded 4,000-character messages, a 65-second HTTP read window and a separate 30-second validation deadline. Cancellation is cooperative; guaranteed termination of arbitrary XPath operations would require process-isolated workers.</p>'''
+ table(['Upload framing', 'Requests', 'Decoded XML each', 'HTTP outcomes'], [(r['framing'], r['uploads'], '20 MiB', ', '.join(map(str, r['httpStatuses']))) for r in upload['rounds']])
+ '<p>All ' + e(upload['healthSamples']) + ' readiness samples passed; post-load validation passed. This regression uses the full local operator pack.</p>')
section('verification', 'Verification and independent evidence', table(['Check', 'Recorded result'], [('JavaScript', str(coverage['javascriptTests']) + ' passed; legacy/API/UI race regressions.'), ('Java', str(coverage['javaTests']) + ' passed, including both complete official packages.'), ('Python', str(coverage['pythonTests']) + ' passed; encoded XML, import boundaries and runtime locks.'), ('Reference', str(len(reference['cases'])) + ' targeted synthetic comparisons passed against HL7 FHIR Validator 7.0.6.'), ('Constrained heap', 'Six concurrent maximum-size uploads in both framing modes; all completed without retry or OOM.'), ('Browser', coverage.get('browserVerification', 'Pending fresh follow-up verification.')), ('CI', 'See PR #53 for results on the exact pushed commit; local evidence does not imply remote CI passed.')])
+ '<p>' + e(reference['terminology']) + ' ' + e(reference['scope']) + '</p><div class="callout warning">' + e(reference['broadComparison']) + '</div>' + details('Targeted reference inputs and outcomes', reference))
bench = coverage['benchmark']
section('performance', 'Measured performance', '<p>' + e(bench['method']) + ' The local ARM64 container has two workers, two CPUs and a 1.5 GiB memory limit; the full local pack is mounted.</p>' + table(['Profile / fixture bytes', 'Concurrency', 'Requests/s', 'HTTP p50', 'HTTP p95', 'Engine p50'], [(r['profile'] + ' / ' + str(r['bytes']), r['concurrency'], r['requestsPerSecond'], str(r['httpP50Ms']) + ' ms', str(r['httpP95Ms']) + ' ms', str(r['engineP50Ms']) + ' ms') for r in bench['results']]) + '<p>Each scenario uses 15 warm-up requests followed by 100 measured requests. Error counts were consistent. These small public fixtures do not cover real-world document variety or establish an industry speed ranking. Earlier preview baselines remain in reports/benchmark.json and are not presented as current results.</p>')
section('deployment', 'Deployment, updates and ownership', '''<pre>docker compose up --build -d
# Open http://localhost:17643
# Select a different host port if necessary:
CDA_VALIDATOR_PORT=17644 docker compose up -d</pre>
<p>The service binds locally by default. Compose mounts operator terminology read-only. The multi-stage build separates verified asset preparation, Java compilation/tests and the minimal runtime. The release workflow publishes versioned AMD64/ARM64 images with SBOM/provenance; merging alone does not publish. npm client and container are separate artifacts.</p>
<p>Weekly checks compare official HL7 releases and the selected Java LTS against their locks. Updates require source, coverage, test and memory review; no silent runtime rule updates occur.</p>
<p>Changes use descriptive work branches and owner-authorized PRs. No development-tool names are allowed in branch names. No direct merges/pushes to main are allowed. The owner can merge their own PR after checks. Public issues remain enabled. GitHub cannot prevent outside PR creation on a public repository while independently retaining public issues; merge policy is enforced instead.</p>
<p>PR #53 requires the owner's explicit merge instruction. Stable release and npm latest promotion have not happened in this report. The compatibility and validation scope must be reviewed before release; publishing does not turn the product into full clinical certification.</p>''')
section('reproduce', 'Reproduce and inspect', '''<pre>npm ci --ignore-scripts
npm test
python3 -m unittest discover -s test -p 'test_*.py'
npm run service:test              # patched JDK 25 locally
# Or build and run the container without host Java:
docker build -t cda-validator:coverage-followup .
python3 scripts/check-java-runtime.py --image cda-validator:coverage-followup
python3 scripts/check-java-runtime.py --upstream
python3 scripts/check-upstream.py
python3 scripts/check-upload-memory.py --image cda-validator:coverage-followup \
  --terminology-dir /private/path/terminology
python3 scripts/benchmark.py --requests 100 --concurrency 1 2 4
python3 scripts/build-report.py</pre>
<p>Source map: service/src/main/java for engine/adapters; service/web for UI/OpenAPI; profiles/*.lock.json for source/runtime recipes; scripts/ for preparation and verification; validator.js and validator.d.ts for legacy and modern clients; reports/ for sanitized evidence.</p>
<p>Application code is MIT licensed. Original JavaScript work by Eric Wadkins was developed further by Priyaranjan (Raj) Tokachichu. John D'Amore's public examples are credited in fixtures; sample influence is distinct from verified code ancestry. Original notices remain. <strong>This product includes software developed by Health Level Seven.</strong></p>'''
+ details('Current sanitized verification evidence', coverage))
nav = ''.join('<a href="#' + anchor + '">' + f'{i:02d}' + ' / ' + e(title) + '</a>' for i, (anchor, title, _) in enumerate(sections, 1))
body = ''.join('<section id="' + anchor + '"><h2><span>' + f'{i:02d}' + '</span>' + e(title) + '</h2>' + content + '</section>' for i, (anchor, title, content) in enumerate(sections, 1))
html = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CDA Validator · Architecture and verification</title><style>
:root{--ink:#1e293b;--muted:#64748b;--blue:#2563eb;--line:#dbe3ef;--paper:#f6f8fc}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.75 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:var(--blue);text-underline-offset:3px}header{background:#172440;color:white;padding:55px max(5%,calc((100vw - 1180px)/2)) 40px}header p{max-width:800px;color:#d6e2f7;font-size:17px}.kicker{font:11px ui-monospace,monospace;letter-spacing:2px;color:#bdd1f7}h1{font-size:clamp(34px,5vw,54px);line-height:1.15;font-weight:550;letter-spacing:-1.7px}.meta{font:12px ui-monospace,monospace;color:#b8c9e8}.layout{max-width:1280px;margin:auto;display:grid;grid-template-columns:205px minmax(0,1fr);gap:42px;padding:38px 30px}nav{position:sticky;top:20px;align-self:start;font-size:11px}nav a{display:block;padding:6px 0;color:var(--muted);text-decoration:none}main{min-width:0}section{scroll-margin-top:20px;border-bottom:1px solid var(--line);padding-bottom:32px;margin-bottom:32px}h2{font-size:24px;letter-spacing:-.5px;line-height:1.3}h2 span{font:11px ui-monospace,monospace;color:var(--blue);margin-right:12px}p{margin:0 0 16px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:24px 0}.card{background:#fff;padding:20px;border:1px solid var(--line);border-radius:6px}.card strong{display:block;font:30px ui-monospace,monospace;color:var(--blue)}.card span{font-size:11px;color:var(--muted)}.callout{padding:18px 20px;background:#eff5ff;border:1px solid #cbdcf7;border-radius:6px;margin:20px 0;font-size:13px}.warning{background:#fff6e3;border-color:#e7d6ae;color:#78551a}.flow{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0}.flow div{flex:1;min-width:125px;padding:16px 12px;border:1px solid var(--line);border-top:3px solid var(--blue);border-radius:4px;background:white;font-size:11px}.flow b{align-self:center;color:var(--blue)}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:11px;line-height:1.6;margin:20px 0}td,th{padding:11px 10px;border-bottom:1px solid var(--line);vertical-align:top;text-align:left;overflow-wrap:anywhere}th{background:#eef2f8;font-size:10px;color:var(--muted)}code,pre{font-family:ui-monospace,SFMono-Regular,Consolas,monospace}code{font-size:.85em}pre{padding:18px;background:#172440;color:#e5ecfb;border-radius:6px;font-size:11px;line-height:1.7;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere}details{border:1px solid var(--line);border-radius:5px;padding:12px 15px;margin:16px 0;font-size:12px}summary{cursor:pointer;font-weight:600}footer{font-size:11px;color:var(--muted);padding:0 0 35px}@media(max-width:850px){.layout{display:block;padding:25px 20px}nav{position:static;display:flex;flex-wrap:wrap;gap:10px;margin-bottom:30px}nav a{padding:0}.cards{grid-template-columns:repeat(2,1fr)}.flow b{display:none}header{padding:36px 20px}}@media print{body{background:white;font-size:11px}header{background:white;color:#111;padding:10px}header p,.meta,.kicker{color:#444}nav{display:none}.layout{display:block;padding:0}pre{background:#f3f3f3;color:#111}h1{font-size:30px}section{break-inside:avoid}}
</style></head><body><header><div class="kicker">CDA VALIDATOR / ENGINEERING REPORT</div><h1>Local validation.<br>Explicit coverage. Reproducible sources.</h1><p>Architecture, design, source data, patched runtime, interoperability and measured verification for the containerized service.</p><div class="meta">Unreleased PR #53 candidate · Evidence: ''' + e(coverage['verifiedAt']) + '</div></header><div class="layout"><nav aria-label="Report sections">' + nav + '</nav><main>' + body + '<footer>Only synthetic/public fixtures and sanitized metadata are included. No patient uploads or operator terminology membership data appear in this report.</footer></main></div></body></html>'
(REPORTS / 'architecture.html').write_text(html)
(ROOT / 'service/web/architecture.html').write_text(html)
print('Generated reports/architecture.html and service/web/architecture.html')
